/**
 * Clean-Room High-Fidelity Anatomical SVG Tooth Geometry for DenToRa
 *
 * Coordinate space: 64 x 100 viewBox.
 *   Maxillary frame: cervical (gum) line at y ≈ 46, crowns extend DOWN to the
 *   occlusal plane (y ≈ 93), roots extend UP to y ≈ 4.
 *   Mandibular frame: generated by vertical mirroring (y → 100 − y) so crowns
 *   face UP toward the occlusal plane and roots extend DOWN to y ≈ 96.
 *
 * Every tooth class is authored as a layered 2.5D illustration:
 *   1. volumetric root trunks (separate shapes with open inter-radicular space)
 *   2. furcation depth shadows
 *   3. enamel crown body with warm ivory gradient
 *   4. clipped interior shading (cervical, distal, incisal translucency)
 *   5. occlusal table plate with raised cusp highlights + recessed grooves
 *   6. glossy specular labial sheen
 *   7. faint translucent pulp chamber & root canals
 *
 * All path data is authored from first human dental anatomical principles.
 * Left-sided teeth (Q2/Q3) are derived by horizontal mirroring of the right
 * master forms so distal root curvature and incisal asymmetry face the arch.
 */

import {
  ToothAnatomyGroup,
  ToothPosition,
  ToothSide,
  ToothSpecificType,
} from '../types/odontogram'

// ─── PUBLIC GEOMETRY CONTRACT ────────────────────────────────────────────────

export interface ToothGeometryPaths {
  rootOutline: string
  rootDetails?: string[]
  crownOutline: string
  crownDetails?: string[]
  pulpOutline: string
  rootCanalPaths: string[]
  surfaces: {
    mesial: string
    distal: string
    occlusal: string
    buccal: string
    lingual: string
  }
  implantOutline: string
  implantThreads: string[]
  crownCapOutline: string
  apexCenter: { x: number; y: number }
  apices?: Array<{ x: number; y: number }>
  gumLinePath: string
  fractureCrackPath: string
  fissurePaths?: string[]
  cuspHighlights?: string[]
  rootSeparationPath?: string
  cervicalLinePath?: string
  rootCount: number
  canalCount: number
  relativeWidth?: number

  // ── Volumetric 2.5D layering (new) ──
  /** Separate root trunk silhouettes (1 = single, 2 = bifurcated, 3 = trifurcated). */
  rootTrunks: string[]
  /** Soft dark blobs at root apices. */
  rootApexShadows: VolBlob[]
  /** Engraved developmental grooves running down root trunks. */
  rootGrooves: string[]
  /** Dark soft shapes in the inter-radicular furcation notches. */
  furcationShadows: string[]
  /** Merged cervical base block extending root trunks behind the crown. */
  cervicalSkirt?: string
  /** Blurred interior crown shadows (cervical band, side falloff, incisal translucency). */
  crownShades: VolBlob[]
  /** Soft cusp-base / fossa shadows rendered ON the occlusal table. */
  occlusalShades: VolBlob[]
  /** Interior light: cusp highlights, labial gloss, incisal translucency. */
  crownLights: VolBlob[]
  /** Recessed occlusal table plate (molars/premolars). */
  occlusalTablePath?: string
  /** Soft shadow band where the table plate meets the labial face. */
  tableTopShade?: VolBlob
  /** Engraved grooves on the occlusal table. */
  occlusalGrooves: string[]
  /** Light ridge lines on the occlusal table (oblique ridge etc.). */
  occlusalRidges?: string[]
}

/** A soft elliptical shading/light blob. */
export interface VolBlob {
  cx: number
  cy: number
  rx: number
  ry: number
  fill: string
  opacity: number
  /** 'soft' = σ1 blur, 'wide' = σ2 blur, undefined = crisp. */
  blur?: 'soft' | 'wide'
  /** Render with the shared radial cusp-light gradient (used for cusp volumes). */
  radial?: boolean
  /** Clockwise rotation in degrees around (cx, cy) — oriented cusp ridges. */
  rot?: number
}

export interface BBox {
  x0: number
  x1: number
  y0: number
  y1: number
}

// ─── PATH TRANSFORM UTILITIES ────────────────────────────────────────────────
// Every authored path uses `M x,y C x,y x,y x,y ... Q x,y x,y Z` token pairs,
// which makes coordinate transforms safe and deterministic.

const r1 = (n: number) => Math.round(n * 10) / 10

function transformPathD(d: string, fx: number, fy: number, ox = 32, oy = 50): string {
  const tokens = d.trim().split(/\s+/)
  const out: string[] = []
  for (const t of tokens) {
    if (t.length > 0 && /[A-Za-z]/.test(t.charAt(0))) {
      out.push(t)
    } else {
      const [xs, ys] = t.split(',').map(Number)
      out.push(`${r1(ox + (xs - ox) * fx)},${r1(oy + (ys - oy) * fy)}`)
    }
  }
  return out.join(' ')
}

function transformBlob(b: VolBlob, fx: number, fy: number, ox = 32, oy = 50): VolBlob {
  return {
    ...b,
    cx: r1(ox + (b.cx - ox) * fx),
    cy: r1(oy + (b.cy - oy) * fy),
    rx: Math.max(0.3, r1(b.rx * Math.abs(fx))),
    ry: Math.max(0.3, r1(b.ry * Math.abs(fy))),
    // A single-axis mirror flips handedness: the ridge angle must negate.
    ...(b.rot !== undefined && fx * fy < 0 ? { rot: -b.rot } : {}),
  }
}

function transformPts(pts: Array<{ x: number; y: number }>, fx: number, fy: number, ox = 32, oy = 50) {
  return pts.map((p) => ({ x: r1(ox + (p.x - ox) * fx), y: r1(oy + (p.y - oy) * fy) }))
}

/** Horizontal mirror (left-sided teeth). */
function flipX(d: string) {
  return transformPathD(d, -1, 1)
}
function flipXBlob(b: VolBlob) {
  return transformBlob(b, -1, 1)
}
/** Vertical mirror (mandibular frame). */
function mirrorY(d: string) {
  return transformPathD(d, 1, -1)
}
function mirrorYBlob(b: VolBlob) {
  return transformBlob(b, 1, -1)
}

function pathBBox(d: string): BBox {
  let x0 = Infinity
  let x1 = -Infinity
  let y0 = Infinity
  let y1 = -Infinity
  for (const t of d.trim().split(/\s+/)) {
    if (/[A-Za-z]/.test(t.charAt(0))) continue
    const [xs, ys] = t.split(',').map(Number)
    x0 = Math.min(x0, xs)
    x1 = Math.max(x1, xs)
    y0 = Math.min(y0, ys)
    y1 = Math.max(y1, ys)
  }
  return { x0, x1, y0, y1 }
}

function rectPath(x0: number, y0: number, x1: number, y1: number): string {
  return `M ${r1(x0)},${r1(y0)} L ${r1(x1)},${r1(y0)} L ${r1(x1)},${r1(y1)} L ${r1(x0)},${r1(y1)} Z`
}

/**
 * Five-surface interactive partition of the crown bounding box.
 * Zones are plain rectangles; the SVG clips them to the organic crown
 * silhouette so hover fills always follow the enamel contour.
 */
function buildSurfaces(bb: BBox, isRightSide: boolean, isUpper: boolean): ToothGeometryPaths['surfaces'] {
  const x0 = bb.x0 + 0.4
  const x1 = bb.x1 - 0.4
  const y0 = bb.y0 + 0.6
  const y1 = bb.y1 - 0.4
  const w = x1 - x0
  const h = y1 - y0
  const side = w * 0.22

  const [mX0, mX1] = isRightSide ? [x0, x0 + side] : [x1 - side, x1]
  const [dX0, dX1] = isRightSide ? [x1 - side, x1] : [x0, x0 + side]
  const cX0 = Math.min(mX1, dX0)
  const cX1 = Math.max(mX0, dX1)

  // Maxillary: buccal (labial) band near cervical, lingual band mid, occlusal band at edge.
  // Mandibular: buccal band near incisal edge, occlusal mid, lingual near cervical.
  const b1 = isUpper ? y0 + h * 0.36 : y0 + h * 0.3
  const b2 = isUpper ? y0 + h * 0.68 : y0 + h * 0.66

  const midRect = rectPath(cX0, b1, cX1, b2)
  const edgeRect = rectPath(cX0, b2, cX1, y1)

  return {
    mesial: rectPath(mX0, y0, mX1, y1),
    distal: rectPath(dX0, y0, dX1, y1),
    buccal: rectPath(cX0, y0, cX1, b1),
    lingual: isUpper ? midRect : edgeRect,
    occlusal: isUpper ? edgeRect : midRect,
  }
}

// ─── INTERNAL CLASS CONFIG (right-sided maxillary master frame) ──────────────

interface CrownBase {
  outline: string
  details: string[]
  shades: VolBlob[]
  lights: VolBlob[]
  pulp: string
  gum: string
  cervical: string
  relWidth: number
  apexCenter: { x: number; y: number }
}

interface OcclusalSet {
  table?: string
  tableTopShade?: VolBlob
  shades: VolBlob[]
  lights: VolBlob[]
  grooves: string[]
  ridges?: string[]
}

interface RootSet {
  trunks: string[]
  furcations: string[]
  apexShadows: VolBlob[]
  grooves: string[]
  canals: string[]
  apices: Array<{ x: number; y: number }>
  rootCount: number
  canalCount: number
}

interface ToothClass {
  crown: CrownBase
  occlusal: OcclusalSet
  roots: RootSet
  fracture: string
}

// Shared warm shading palette
const SHADE_DISTAL = '#8A744E'
const SHADE_MESIAL = '#8A744E'
const SHADE_CERVICAL = '#C9A85C'
const SHADE_INCISAL = '#6B7E94'
const SHADE_CUSP = '#7A6030'
const LIGHT = '#FFFFFF'

const cuspLight = (cx: number, cy: number, r: number, o = 0.8): VolBlob => ({
  cx,
  cy,
  rx: r,
  ry: r,
  fill: LIGHT,
  opacity: o,
  radial: true,
})
/** Elongated, optionally tilted cusp-ridge highlight — reads as a sculpted mound. */
const cuspRidge = (cx: number, cy: number, rx: number, ry: number, rot = 0, o = 0.9): VolBlob => ({
  cx,
  cy,
  rx,
  ry,
  rot,
  fill: LIGHT,
  opacity: o,
  radial: true,
})
const cuspShade = (cx: number, cy: number, rx: number, ry: number, o = 0.3): VolBlob => ({
  cx,
  cy,
  rx,
  ry,
  fill: SHADE_CUSP,
  opacity: o,
  blur: 'wide',
})
const gloss = (cx: number, cy: number, rx: number, ry: number, o = 0.4): VolBlob => ({
  cx,
  cy,
  rx,
  ry,
  fill: LIGHT,
  opacity: Math.min(0.62, o * 1.15),
  blur: 'wide',
})
const edgeShade = (cx: number, cy: number, rx: number, ry: number, o = 0.25, fill = SHADE_DISTAL): VolBlob => ({
  cx,
  cy,
  rx,
  ry,
  fill,
  opacity: Math.min(0.5, o * 1.45),
  blur: 'wide',
})
const cervical = (cx: number, cy: number, rx: number, ry: number, o = 0.2): VolBlob => ({
  cx,
  cy,
  rx,
  ry,
  fill: SHADE_CERVICAL,
  opacity: Math.min(0.45, o * 1.3),
  blur: 'wide',
})
const apexShadow = (x: number, y: number, rx: number, ry: number): VolBlob => ({
  cx: x,
  cy: y,
  rx,
  ry,
  fill: '#5C420F',
  opacity: 0.45,
  blur: 'soft',
})

