// ══════════════════════════════════════════════════════════════════════════════

/** Lower crown: reuse the maxillary crown base with a class width factor. */
function lowerCrown(upper: CrownBase, fx: number): CrownBase {
  return {
    outline: transformPathD(upper.outline, fx, 1),
    details: upper.details.map((d) => transformPathD(d, fx, 1)),
    shades: upper.shades.map((b) => transformBlob(b, fx, 1)),
    lights: upper.lights.map((b) => transformBlob(b, fx, 1)),
    pulp: transformPathD(upper.pulp, fx, 1),
    gum: upper.gum,
    cervical: upper.cervical,
    relWidth: Math.round(upper.relWidth * fx * 100) / 100,
    apexCenter: upper.apexCenter,
  }
}

