// ─── ASSEMBLY ────────────────────────────────────────────────────────────────

function implantFor(bb: BBox, isUpper: boolean): { outline: string; threads: string[] } {
  const cx = r1((bb.x0 + bb.x1) / 2)
  const w = Math.min(11, Math.max(7.5, (bb.x1 - bb.x0) * 0.28))
  const top = isUpper ? 10 : 90
  const bot = isUpper ? 47 : 53
  const outline =
    `M ${r1(cx - w / 2)},${bot} L ${r1(cx + w / 2)},${bot} ` +
    `L ${r1(cx + w / 2 - 1.2)},${r1(top + 8)} C ${r1(cx + w / 2 - 1.2)},${top} ${r1(cx - w / 2 + 1.2)},${top} ${r1(cx - w / 2 + 1.2)},${r1(top + 8)} Z`
  const threads: string[] = []
  const start = isUpper ? top + 6 : bot - 6
  const dir = isUpper ? 1 : -1
  for (let i = 0; i < 5; i++) {
    const y = r1(start + dir * (i + 1) * 6.5)
    const t = i / 4
    const tw = r1((w - 1.5) * (1 - t * 0.35) / 2)
    threads.push(`M ${r1(cx - tw)},${y} L ${r1(cx + tw)},${y}`)
  }
  return { outline, threads }
}

function assemble(cls: ToothClass): Omit<ToothGeometryPaths, 'surfaces'> {
  const c = cls.crown
  const oc = cls.occlusal
  const rt = cls.roots
  return {
    rootOutline: rt.trunks.join(' '),
    rootDetails: rt.grooves,
    crownOutline: c.outline,
    crownDetails: c.details,
    pulpOutline: c.pulp,
    rootCanalPaths: rt.canals,
    implantOutline: '',
    implantThreads: [],
    crownCapOutline: '',
    apexCenter: c.apexCenter,
    apices: rt.apices,
    gumLinePath: c.gum,
    fractureCrackPath: cls.fracture,
    fissurePaths: oc.grooves,
    cuspHighlights: oc.ridges ?? [],
    rootSeparationPath: rt.furcations.join(' ') || undefined,
    cervicalLinePath: c.cervical,
    rootCount: rt.rootCount,
    canalCount: rt.canalCount,
    relativeWidth: c.relWidth,
    rootTrunks: rt.trunks,
    rootApexShadows: rt.apexShadows,
    rootGrooves: rt.grooves,
    furcationShadows: rt.furcations,
    crownShades: c.shades,
    occlusalShades: oc.shades,
    crownLights: [...c.lights, ...oc.lights],
    occlusalTablePath: oc.table,
    tableTopShade: oc.tableTopShade,
    occlusalGrooves: oc.grooves,
    occlusalRidges: oc.ridges,
  }
}

function finalize(g: Omit<ToothGeometryPaths, 'surfaces'>, isRightSide: boolean, isUpper: boolean): ToothGeometryPaths {
  const bb = pathBBox(g.crownOutline)
  const cx = (bb.x0 + bb.x1) / 2
  const cy = (bb.y0 + bb.y1) / 2
  const cap = transformPathD(g.crownOutline, 1.07, 1.07, cx, cy)
  const implant = implantFor(bb, isUpper)
  const fracture =
    `M ${r1(cx - 9)},${r1(bb.y0 + 2.5)} L ${r1(cx - 1)},${r1(cy)} L ${r1(cx - 5)},${r1(cy + (bb.y1 - cy) * 0.45)} L ${r1(cx + 6)},${r1(bb.y1 - 1.5)}`
  // Merged cervical base: extends the root trunks down behind the crown so the
  // trunk base edges never step out above the cervical line.
  let skirt: string | undefined
  if (g.rootTrunks.length > 0) {
    let x0 = Infinity
    let x1 = -Infinity
    for (const t of g.rootTrunks) {
      const b = pathBBox(t)
      x0 = Math.min(x0, b.x0)
      x1 = Math.max(x1, b.x1)
    }
    // Clamp to the crown's CERVICAL width (the band the skirt actually spans),
    // taken from the cervical line endpoints — the global bbox is wider on
    // narrowed crowns and let the skirt poke out beside the cervical.
    const cM = g.cervicalLinePath ? /M\s*(-?[\d.]+),\s*(-?[\d.]+)/.exec(g.cervicalLinePath) : null
    const cT = g.cervicalLinePath ? /(-?[\d.]+),\s*(-?[\d.]+)\s*$/.exec(g.cervicalLinePath) : null
    const cervX0 = cM ? +cM[1] : bb.x0 + 1.5
    const cervX1 = cT ? +cT[1] : bb.x1 - 1.5
    x0 = Math.max(x0, Math.min(cervX0, cervX1) + 1.0)
    x1 = Math.min(x1, Math.max(cervX0, cervX1) - 1.0)
    const topY = isUpper ? 49.2 : 44.8
    const botY = isUpper ? 55.5 : 51.5
    skirt = `M ${r1(x0)},${botY} L ${r1(x0)},${topY} Q ${r1((x0 + x1) / 2)},${r1(topY - 1.2)} ${r1(x1)},${topY} L ${r1(x1)},${botY} Z`
  }
  return {
    ...g,
    cervicalSkirt: skirt,
    surfaces: buildSurfaces(bb, isRightSide, isUpper),
    crownCapOutline: cap,
    implantOutline: implant.outline,
    implantThreads: implant.threads,
    fractureCrackPath: fracture,
  }
}

function flipGeometry(g: ToothGeometryPaths): ToothGeometryPaths {
  return {
    ...g,
    rootOutline: g.rootTrunks.map(flipX).join(' '),
    crownOutline: flipX(g.crownOutline),
    crownDetails: g.crownDetails?.map(flipX),
    pulpOutline: flipX(g.pulpOutline),
    rootCanalPaths: g.rootCanalPaths.map(flipX),
    implantOutline: flipX(g.implantOutline),
    implantThreads: g.implantThreads.map(flipX),
    crownCapOutline: flipX(g.crownCapOutline),
    apexCenter: { x: r1(64 - g.apexCenter.x), y: g.apexCenter.y },
    apices: g.apices?.map((p) => ({ x: r1(64 - p.x), y: p.y })),
    gumLinePath: flipX(g.gumLinePath),
    fractureCrackPath: flipX(g.fractureCrackPath),
    fissurePaths: g.fissurePaths?.map(flipX),
    cuspHighlights: g.cuspHighlights?.map(flipX),
    rootSeparationPath: g.rootSeparationPath ? flipX(g.rootSeparationPath) : undefined,
    cervicalSkirt: g.cervicalSkirt ? flipX(g.cervicalSkirt) : undefined,
    cervicalLinePath: g.cervicalLinePath ? flipX(g.cervicalLinePath) : undefined,
    rootTrunks: g.rootTrunks.map(flipX),
    rootApexShadows: g.rootApexShadows.map(flipXBlob),
    rootGrooves: g.rootGrooves.map(flipX),
    furcationShadows: g.furcationShadows.map(flipX),
    crownShades: g.crownShades.map(flipXBlob),
    occlusalShades: g.occlusalShades.map(flipXBlob),
    crownLights: g.crownLights.map(flipXBlob),
    occlusalTablePath: g.occlusalTablePath ? flipX(g.occlusalTablePath) : undefined,
    tableTopShade: g.tableTopShade ? flipXBlob(g.tableTopShade) : undefined,
    occlusalGrooves: g.occlusalGrooves.map(flipX),
    occlusalRidges: g.occlusalRidges?.map(flipX),
    // Mesial/distal swap under horizontal mirror
    surfaces: {
      mesial: g.surfaces.distal,
      distal: g.surfaces.mesial,
      occlusal: g.surfaces.occlusal,
      buccal: g.surfaces.buccal,
      lingual: g.surfaces.lingual,
    },
  }
}

// ─── PROPORTIONAL REFINEMENT PASS ────────────────────────────────────────────
// Widen crowns toward real mesiodistal proportions and trim roots (thinner,
// shorter, tighter taper) without re-authoring the hand-tuned curves.

function scaleClass(cls: ToothClass, crownFx: number, rootFx: number, rootFy: number): ToothClass {
  const bb = pathBBox(cls.crown.outline)
  const cx = (bb.x0 + bb.x1) / 2
  const sc = (d: string, fx: number, fy: number, oy = 48) => transformPathD(d, fx, fy, cx, oy)
  const sb = (b: VolBlob, fx: number, fy: number, oy = 48) => transformBlob(b, fx, fy, cx, oy)
  return {
    ...cls,
    crown: {
      ...cls.crown,
      outline: sc(cls.crown.outline, crownFx, 1),
      details: cls.crown.details.map((d) => sc(d, crownFx, 1)),
      shades: cls.crown.shades.map((b) => sb(b, crownFx, 1)),
      lights: cls.crown.lights.map((b) => sb(b, crownFx, 1)),
      pulp: sc(cls.crown.pulp, crownFx, 1),
      gum: sc(cls.crown.gum, crownFx, 1),
      cervical: sc(cls.crown.cervical, crownFx, 1),
    },
    occlusal: {
      ...cls.occlusal,
      table: cls.occlusal.table ? sc(cls.occlusal.table, crownFx, 1) : undefined,
      tableTopShade: cls.occlusal.tableTopShade ? sb(cls.occlusal.tableTopShade, crownFx, 1) : undefined,
      shades: cls.occlusal.shades.map((b) => sb(b, crownFx, 1)),
      lights: cls.occlusal.lights.map((b) => sb(b, crownFx, 1)),
      grooves: cls.occlusal.grooves.map((d) => sc(d, crownFx, 1)),
      ridges: cls.occlusal.ridges?.map((d) => sc(d, crownFx, 1)),
    },
    roots: {
      ...cls.roots,
      trunks: cls.roots.trunks.map((d) => sc(d, rootFx, rootFy)),
      furcations: cls.roots.furcations.map((d) => sc(d, rootFx, rootFy)),
      apexShadows: cls.roots.apexShadows.map((b) => sb(b, rootFx, rootFy)),
      grooves: cls.roots.grooves.map((d) => sc(d, rootFx, rootFy)),
      canals: cls.roots.canals.map((d) => sc(d, rootFx, rootFy)),
      apices: cls.roots.apices.map((p) => ({ x: r1(cx + (p.x - cx) * rootFx), y: r1(48 + (p.y - 48) * rootFy) })),
    },
  }
}

